/* ------------------------------------------------------------------ */
/* Helpers / hooks                                                    */
/* ------------------------------------------------------------------ */

function prefersReducedMotion() {
  if (typeof window === "undefined") return false;
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

function useReveal(threshold = 0.15) {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (prefersReducedMotion()) {
      setVisible(true);
      return;
    }
    const obs = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setVisible(true);
            obs.unobserve(el);
          }
        });
      },
      { threshold }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, [threshold]);
  return [ref, visible];
}

function Reveal({ children, className = "", delay = 0, as: Tag = "div" }) {
  const [ref, visible] = useReveal();
  return (
    <Tag
      ref={ref}
      className={`pk-reveal ${visible ? "pk-reveal-visible" : ""} ${className}`}
      style={{ transitionDelay: `${delay}ms` }}
    >
      {children}
    </Tag>
  );
}

function useTypewriter(words, speed = 65, pause = 1500) {
  const [text, setText] = useState("");
  const [index, setIndex] = useState(0);
  const [deleting, setDeleting] = useState(false);

  useEffect(() => {
    if (prefersReducedMotion()) {
      setText(words[0]);
      return;
    }
    const current = words[index % words.length];
    let timeout;
    if (!deleting && text.length < current.length) {
      timeout = setTimeout(() => setText(current.slice(0, text.length + 1)), speed);
    } else if (!deleting && text.length === current.length) {
      timeout = setTimeout(() => setDeleting(true), pause);
    } else if (deleting && text.length > 0) {
      timeout = setTimeout(() => setText(current.slice(0, text.length - 1)), speed / 2);
    } else if (deleting && text.length === 0) {
      setDeleting(false);
      setIndex((i) => i + 1);
    }
    return () => clearTimeout(timeout);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [text, deleting, index]);

  return text;
}

function useScrollSpy(ids) {
  const [active, setActive] = useState(ids[0]);
  useEffect(() => {
    const elements = ids
      .map((id) => document.getElementById(id))
      .filter(Boolean);
    if (!elements.length) return;
    const obs = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) setActive(entry.target.id);
        });
      },
      { rootMargin: "-40% 0px -50% 0px", threshold: 0 }
    );
    elements.forEach((el) => obs.observe(el));
    return () => obs.disconnect();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  return active;
}

function scrollToId(id) {
  const el = document.getElementById(id);
  if (!el) return;
  el.scrollIntoView({
    behavior: prefersReducedMotion() ? "auto" : "smooth",
    block: "start",
  });
}

/* ------------------------------------------------------------------ */
/* Three.js hero visual — orbiting component graph                    */
/* ------------------------------------------------------------------ */

function makeGlowTexture() {
  const size = 128;
  const canvas = document.createElement("canvas");
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext("2d");
  const gradient = ctx.createRadialGradient(
    size / 2,
    size / 2,
    0,
    size / 2,
    size / 2,
    size / 2
  );
  gradient.addColorStop(0, "rgba(255,255,255,1)");
  gradient.addColorStop(0.35, "rgba(255,255,255,0.85)");
  gradient.addColorStop(1, "rgba(255,255,255,0)");
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, size, size);
  return new THREE.CanvasTexture(canvas);
}

function buildNetwork(scene) {
  const group = new THREE.Group();
  const glowTex = makeGlowTexture();
  const palette = [0xb490f5, 0x5fd3f3, 0x7ee8a0, 0xf5a97f];
  const disposables = [glowTex];

  // Outer icosahedron: edges + glowing vertex nodes
  const outerGeo = new THREE.IcosahedronGeometry(2.35, 0);
  const outerEdgesGeo = new THREE.EdgesGeometry(outerGeo);
  const outerLineMat = new THREE.LineBasicMaterial({
    color: 0x3a4a7a,
    transparent: true,
    opacity: 0.6,
  });
  const outerLines = new THREE.LineSegments(outerEdgesGeo, outerLineMat);
  group.add(outerLines);
  disposables.push(outerGeo, outerEdgesGeo, outerLineMat);

  const posAttr = outerGeo.attributes.position;
  const positions = [];
  const colors = [];
  const colorObj = new THREE.Color();
  for (let i = 0; i < posAttr.count; i++) {
    positions.push(posAttr.getX(i), posAttr.getY(i), posAttr.getZ(i));
    colorObj.set(palette[i % palette.length]);
    colors.push(colorObj.r, colorObj.g, colorObj.b);
  }
  const nodesGeo = new THREE.BufferGeometry();
  nodesGeo.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
  nodesGeo.setAttribute("color", new THREE.Float32BufferAttribute(colors, 3));
  const nodesMat = new THREE.PointsMaterial({
    size: 0.26,
    map: glowTex,
    vertexColors: true,
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    sizeAttenuation: true,
  });
  const nodePoints = new THREE.Points(nodesGeo, nodesMat);
  group.add(nodePoints);
  disposables.push(nodesGeo, nodesMat);

  // Inner rotated icosahedron for depth
  const innerGeo = new THREE.IcosahedronGeometry(1.3, 0);
  const innerEdgesGeo = new THREE.EdgesGeometry(innerGeo);
  const innerLineMat = new THREE.LineBasicMaterial({
    color: 0x5fd3f3,
    transparent: true,
    opacity: 0.4,
  });
  const innerLines = new THREE.LineSegments(innerEdgesGeo, innerLineMat);
  innerLines.rotation.set(0.6, 0.4, 0.2);
  group.add(innerLines);
  disposables.push(innerGeo, innerEdgesGeo, innerLineMat);

  // Ambient particle field
  const starCount = 220;
  const starPositions = [];
  for (let i = 0; i < starCount; i++) {
    const r = 5 + Math.random() * 4.5;
    const theta = Math.random() * Math.PI * 2;
    const phi = Math.acos(Math.random() * 2 - 1);
    starPositions.push(
      r * Math.sin(phi) * Math.cos(theta),
      r * Math.sin(phi) * Math.sin(theta),
      r * Math.cos(phi)
    );
  }
  const starGeo = new THREE.BufferGeometry();
  starGeo.setAttribute("position", new THREE.Float32BufferAttribute(starPositions, 3));
  const starMat = new THREE.PointsMaterial({
    size: 0.055,
    color: 0x8b93b5,
    map: glowTex,
    transparent: true,
    opacity: 0.55,
    depthWrite: false,
    sizeAttenuation: true,
  });
  const stars = new THREE.Points(starGeo, starMat);
  disposables.push(starGeo, starMat);

  scene.add(stars);
  scene.add(group);

  return {
    group,
    stars,
    dispose: () => disposables.forEach((d) => d.dispose && d.dispose()),
  };
}

function HeroCanvas() {
  const containerRef = useRef(null);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return undefined;

    const reduced = prefersReducedMotion();
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(
      45,
      container.clientWidth / Math.max(container.clientHeight, 1),
      0.1,
      100
    );
    camera.position.set(0, 0, 7.4);

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.setSize(container.clientWidth, container.clientHeight);
    container.appendChild(renderer.domElement);

    const { group, stars, dispose } = buildNetwork(scene);

    let targetRotX = 0.15;
    let targetRotY = 0.3;
    let curRotX = 0.15;
    let curRotY = 0.3;
    let isDragging = false;
    let autoRotate = true;
    let lastX = 0;
    let lastY = 0;
    let resumeTimeout;

    const onPointerDown = (e) => {
      isDragging = true;
      autoRotate = false;
      lastX = e.clientX;
      lastY = e.clientY;
      clearTimeout(resumeTimeout);
    };
    const onPointerMove = (e) => {
      if (isDragging) {
        const dx = e.clientX - lastX;
        const dy = e.clientY - lastY;
        lastX = e.clientX;
        lastY = e.clientY;
        targetRotY += dx * 0.006;
        targetRotX += dy * 0.006;
        return;
      }
      const rect = container.getBoundingClientRect();
      if (
        e.clientX < rect.left ||
        e.clientX > rect.right ||
        e.clientY < rect.top ||
        e.clientY > rect.bottom
      )
        return;
      const nx = ((e.clientX - rect.left) / rect.width) * 2 - 1;
      const ny = ((e.clientY - rect.top) / rect.height) * 2 - 1;
      targetRotY = 0.3 + nx * 0.45;
      targetRotX = 0.15 + ny * 0.28;
    };
    const onPointerUp = () => {
      isDragging = false;
      resumeTimeout = setTimeout(() => {
        autoRotate = true;
      }, 1000);
    };

    container.addEventListener("pointerdown", onPointerDown);
    window.addEventListener("pointermove", onPointerMove);
    window.addEventListener("pointerup", onPointerUp);

    let raf;
    const clock = new THREE.Clock();
    const animate = () => {
      raf = requestAnimationFrame(animate);
      const t = clock.getElapsedTime();
      if (autoRotate) targetRotY += 0.0022;
      curRotX += (targetRotX - curRotX) * 0.06;
      curRotY += (targetRotY - curRotY) * 0.06;
      group.rotation.x = curRotX;
      group.rotation.y = curRotY;
      group.position.y = Math.sin(t * 0.6) * 0.1;
      stars.rotation.y = t * 0.02;
      renderer.render(scene, camera);
    };

    if (reduced) {
      renderer.render(scene, camera);
    } else {
      animate();
    }

    const handleResize = () => {
      const w = container.clientWidth;
      const h = Math.max(container.clientHeight, 1);
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h);
      if (reduced) renderer.render(scene, camera);
    };
    window.addEventListener("resize", handleResize);
    const ro = new ResizeObserver(handleResize);
    ro.observe(container);

    return () => {
      cancelAnimationFrame(raf);
      clearTimeout(resumeTimeout);
      window.removeEventListener("resize", handleResize);
      window.removeEventListener("pointermove", onPointerMove);
      window.removeEventListener("pointerup", onPointerUp);
      container.removeEventListener("pointerdown", onPointerDown);
      ro.disconnect();
      dispose();
      renderer.dispose();
      if (renderer.domElement.parentNode) {
        renderer.domElement.parentNode.removeChild(renderer.domElement);
      }
    };
  }, []);

  return <div ref={containerRef} className="pk-canvas-wrap" />;
}

