/* ------------------------------------------------------------------ */
/* Stylesheet                                                         */
/* ------------------------------------------------------------------ */

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=Inter:wght@400;500;600&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

.pk-root {
  --bg: #0A0E1A;
  --panel: #10162A;
  --panel-2: #141B33;
  --border: #232C4D;
  --text: #E6E9F5;
  --muted: #8B93B5;
  --purple: #B490F5;
  --cyan: #5FD3F3;
  --green: #7EE8A0;
  --orange: #F5A97F;

  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  font-family: 'Inter', sans-serif;
  background-image:
    radial-gradient(circle at 1px 1px, rgba(139,147,181,0.14) 1px, transparent 0);
  background-size: 26px 26px;
  overflow-x: hidden;
}

.pk-root * { box-sizing: border-box; }

.f-display { font-family: 'Space Grotesk', sans-serif; }
.f-mono { font-family: 'JetBrains Mono', monospace; }

.pk-root ::selection { background: var(--purple); color: #0A0E1A; }

/* scrollbar */
.pk-root ::-webkit-scrollbar { width: 10px; height: 10px; }
.pk-root ::-webkit-scrollbar-track { background: var(--bg); }
.pk-root ::-webkit-scrollbar-thumb { background: var(--border); border-radius: 6px; }

/* tokens */
.tok-comment { color: var(--muted); font-style: italic; }
.tok-keyword { color: var(--purple); }
.tok-prop { color: var(--cyan); }
.tok-string { color: var(--green); }
.tok-num { color: var(--orange); }
.tok-punct { color: var(--muted); }

/* reveal */
.pk-reveal { opacity: 0; transform: translateY(26px); transition: opacity .7s ease, transform .7s ease; }
.pk-reveal-visible { opacity: 1; transform: translateY(0); }
@media (prefers-reduced-motion: reduce) {
  .pk-reveal { transition: none; opacity: 1; transform: none; }
}

/* nav */
.pk-nav {
  position: sticky; top: 0; z-index: 50;
  background: rgba(10,14,26,0.85);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
}
.pk-nav-inner {
  max-width: 1180px; margin: 0 auto; padding: 14px 24px;
  display: flex; align-items: center; gap: 28px;
}
.pk-logo { display: flex; align-items: center; gap: 8px; color: var(--cyan); flex-shrink: 0; }
.pk-logo-text { font-weight: 600; font-size: 14px; color: var(--text); }
.pk-tabs { display: flex; gap: 4px; overflow-x: auto; scrollbar-width: none; }
.pk-tabs::-webkit-scrollbar { display: none; }
.pk-tab {
  background: transparent; border: 1px solid transparent; color: var(--muted);
  font-size: 12.5px; padding: 7px 12px; border-radius: 8px; cursor: pointer;
  white-space: nowrap; transition: color .2s ease, background .2s ease, border-color .2s ease;
}
.pk-tab:hover { color: var(--text); background: var(--panel-2); }
.pk-tab-active { color: var(--cyan); background: var(--panel); border-color: var(--border); }

/* layout helpers */
.pk-section { padding: 84px 24px; position: relative; }
.pk-section-alt { background: linear-gradient(180deg, transparent, rgba(20,27,51,0.35), transparent); }
.pk-container { max-width: 1180px; margin: 0 auto; }
.pk-container-narrow { max-width: 760px; }
.pk-eyebrow { color: var(--purple); font-size: 13px; margin: 0 0 8px; letter-spacing: 0.02em; }
.pk-h2 { font-size: clamp(28px, 4vw, 40px); font-weight: 700; margin: 0 0 44px; }

/* hero */
.pk-hero { padding-top: 56px; padding-bottom: 40px; }
.pk-hero-grid {
  max-width: 1180px; margin: 0 auto;
  display: grid; grid-template-columns: 1fr; gap: 40px; align-items: center;
}
@media (min-width: 1024px) {
  .pk-hero-grid { grid-template-columns: 1.05fr 0.95fr; gap: 56px; }
}

.pk-code-panel {
  background: var(--panel); border: 1px solid var(--border); border-radius: 14px;
  overflow: hidden; box-shadow: 0 30px 60px -20px rgba(0,0,0,0.6);
}
.pk-window-bar {
  display: flex; align-items: center; gap: 8px;
  padding: 12px 16px; border-bottom: 1px solid var(--border); background: var(--panel-2);
}
.pk-dot { width: 10px; height: 10px; border-radius: 50%; display: inline-block; }
.pk-dot-red { background: #F5716B; }
.pk-dot-yellow { background: #F5C56B; }
.pk-dot-green { background: #7EE8A0; }
.pk-window-title { color: var(--muted); font-size: 12px; margin-left: 6px; }

.pk-code-body { padding: 22px 8px 22px 0; font-size: 13.5px; line-height: 1.85; }
.pk-code-line {
  display: flex; gap: 18px; padding: 0 20px;
  opacity: 0; transform: translateX(-10px);
  transition: opacity .45s ease, transform .45s ease;
}
.pk-code-panel-in .pk-code-line { opacity: 1; transform: translateX(0); transition-delay: calc(var(--i) * 85ms); }
.pk-line-num { color: #3F4A6E; width: 16px; text-align: right; user-select: none; flex-shrink: 0; }
.pk-line-content { white-space: pre-wrap; word-break: break-word; }

.pk-cursor-blink { animation: pk-blink 1s steps(1) infinite; color: var(--cyan); }
@keyframes pk-blink { 50% { opacity: 0; } }

.pk-hero-cta { padding: 4px 24px 24px; border-top: 1px solid var(--border); margin-top: 6px; }
.pk-status { display: flex; align-items: center; gap: 8px; margin-top: 18px; font-size: 12.5px; color: var(--green); }
.pk-status-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--green); box-shadow: 0 0 0 0 rgba(126,232,160,0.6); animation: pk-pulse 2s infinite; }
@keyframes pk-pulse {
  0% { box-shadow: 0 0 0 0 rgba(126,232,160,0.55); }
  70% { box-shadow: 0 0 0 8px rgba(126,232,160,0); }
  100% { box-shadow: 0 0 0 0 rgba(126,232,160,0); }
}
.pk-role-line { display: flex; align-items: center; gap: 6px; color: var(--text); font-size: 15px; margin-top: 12px; min-height: 22px; }
.pk-role-line svg { color: var(--purple); flex-shrink: 0; }

.pk-btn-row { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 20px; }
.pk-btn {
  display: inline-flex; align-items: center; gap: 8px; font-family: 'Space Grotesk', sans-serif;
  font-weight: 600; font-size: 14px; padding: 11px 18px; border-radius: 10px;
  text-decoration: none; cursor: pointer; border: 1px solid transparent; transition: transform .2s ease, box-shadow .2s ease, background .2s ease, border-color .2s ease;
}
.pk-btn-primary { background: linear-gradient(90deg, var(--purple), var(--cyan)); color: #0A0E1A; }
.pk-btn-primary:hover { transform: translateY(-2px); box-shadow: 0 12px 24px -10px rgba(180,144,245,0.55); }
.pk-btn-ghost { background: var(--panel-2); color: var(--text); border-color: var(--border); }
.pk-btn-ghost:hover { border-color: var(--cyan); color: var(--cyan); transform: translateY(-2px); }
.pk-btn-static { display: inline-flex; align-items: center; gap: 8px; color: var(--muted); font-size: 14px; font-family: 'Space Grotesk', sans-serif; padding: 11px 4px; }

.pk-hero-visual { position: relative; display: flex; flex-direction: column; align-items: center; }
.pk-canvas-wrap {
  width: 100%; height: 340px; border-radius: 16px; overflow: hidden; position: relative;
  background: radial-gradient(circle at 50% 45%, rgba(95,211,243,0.08), transparent 60%);
  touch-action: none; cursor: grab;
}
@media (min-width: 1024px) { .pk-canvas-wrap { height: 460px; } }
.pk-canvas-wrap canvas { display: block; }
.pk-canvas-caption { color: var(--muted); font-size: 12px; margin-top: 12px; text-align: center; }

/* marquee */
.pk-marquee-wrap {
  overflow: hidden; border-top: 1px solid var(--border); border-bottom: 1px solid var(--border);
  background: var(--panel); padding: 16px 0;
}
.pk-marquee-track { display: flex; gap: 12px; width: max-content; animation: pk-marquee 32s linear infinite; }
@media (prefers-reduced-motion: reduce) { .pk-marquee-track { animation: none; flex-wrap: wrap; } }
@keyframes pk-marquee { from { transform: translateX(0); } to { transform: translateX(-50%); } }
.pk-chip {
  border: 1px solid var(--border); color: var(--muted); font-size: 12.5px;
  padding: 7px 14px; border-radius: 999px; white-space: nowrap; background: var(--panel-2);
}

/* about */
.pk-about-grid { display: grid; grid-template-columns: 1fr; gap: 40px; }
@media (min-width: 900px) { .pk-about-grid { grid-template-columns: 300px 1fr; gap: 56px; } }
.pk-about-side { display: flex; flex-direction: column; align-items: center; gap: 24px; }
.pk-avatar-ring {
  width: 168px; height: 168px; border-radius: 50%; padding: 4px;
  background: conic-gradient(from 180deg, var(--purple), var(--cyan), var(--green), var(--orange), var(--purple));
}
.pk-avatar { width: 100%; height: 100%; border-radius: 50%; object-fit: cover; display: block; border: 4px solid var(--bg); }
.pk-meta-card { width: 100%; background: var(--panel); border: 1px solid var(--border); border-radius: 12px; padding: 16px 18px; font-size: 12.5px; line-height: 2; }
.pk-meta-row { color: var(--muted); }

.pk-about-copy p { font-size: 16px; line-height: 1.85; color: var(--text); margin: 0 0 18px; }
.pk-about-copy strong { color: var(--cyan); font-weight: 600; }

/* skills */
.pk-skills-grid { display: grid; grid-template-columns: 1fr; gap: 20px; }
@media (min-width: 700px) { .pk-skills-grid { grid-template-columns: 1fr 1fr; } }
.pk-skill-card { background: var(--panel); border: 1px solid var(--border); border-radius: 14px; padding: 22px; transition: border-color .25s ease, transform .25s ease; }
.pk-skill-card:hover { transform: translateY(-4px); }
.pk-c-cyan:hover { border-color: var(--cyan); }
.pk-c-green:hover { border-color: var(--green); }
.pk-c-orange:hover { border-color: var(--orange); }
.pk-c-purple:hover { border-color: var(--purple); }
.pk-skill-title { font-size: 13.5px; margin: 0; }
.pk-skill-close { margin-top: 4px; }
.pk-skill-chips { display: flex; flex-wrap: wrap; gap: 8px; margin: 14px 0 6px 18px; }
.pk-skill-chip { font-size: 12.5px; padding: 6px 12px; border-radius: 8px; background: var(--panel-2); border: 1px solid var(--border); color: var(--text); }

/* projects */
.pk-projects-grid { display: grid; grid-template-columns: 1fr; gap: 22px; }
@media (min-width: 700px) { .pk-projects-grid { grid-template-columns: 1fr 1fr; } }
.pk-project-card {
  background: var(--panel); border: 1px solid var(--border); border-radius: 14px; padding: 22px;
  transition: transform .25s ease, border-color .25s ease, box-shadow .25s ease;
}
.pk-project-link {
  display: block; color: inherit; text-decoration: none;
}
.pk-project-card:hover { transform: translateY(-6px); box-shadow: 0 20px 40px -20px rgba(0,0,0,0.55); }
.pk-c-purple .pk-project-icon { color: var(--purple); background: rgba(180,144,245,0.12); }
.pk-c-cyan .pk-project-icon { color: var(--cyan); background: rgba(95,211,243,0.12); }
.pk-c-green .pk-project-icon { color: var(--green); background: rgba(126,232,160,0.12); }
.pk-c-orange .pk-project-icon { color: var(--orange); background: rgba(245,169,127,0.12); }
.pk-c-purple:hover { border-color: var(--purple); }
.pk-c-cyan:hover { border-color: var(--cyan); }
.pk-c-green:hover { border-color: var(--green); }
.pk-c-orange:hover { border-color: var(--orange); }
.pk-project-head { display: flex; align-items: center; gap: 10px; margin-bottom: 14px; }
.pk-project-icon { width: 34px; height: 34px; border-radius: 9px; display: flex; align-items: center; justify-content: center; }
.pk-project-file { color: var(--muted); font-size: 12px; }
.pk-project-title { font-size: 18px; margin: 0 0 4px; font-weight: 700; }
.pk-project-role { color: var(--muted); font-size: 12px; margin: 0 0 12px; }
.pk-project-desc { font-size: 14.5px; line-height: 1.7; color: var(--text); opacity: 0.9; margin: 0 0 16px; }
.pk-project-tech { display: flex; flex-wrap: wrap; gap: 8px; }
.pk-tech-tag { font-size: 11.5px; padding: 5px 10px; border-radius: 6px; background: var(--panel-2); border: 1px solid var(--border); color: var(--muted); }

/* education timeline */
.pk-timeline { display: flex; flex-direction: column; }
.pk-commit { display: grid; grid-template-columns: 32px 1fr; gap: 18px; }
.pk-commit-line { display: flex; flex-direction: column; align-items: center; }
.pk-commit-dot { width: 32px; height: 32px; border-radius: 50%; background: var(--panel); border: 1px solid var(--border); color: var(--cyan); display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
.pk-commit-stem { width: 2px; flex: 1; background: var(--border); margin: 4px 0; min-height: 40px; }
.pk-commit-body { padding-bottom: 40px; }
.pk-commit-hash { font-size: 12px; color: var(--muted); margin: 4px 0 6px; }
.pk-commit-year { color: var(--orange); }
.pk-commit-title { display: flex; align-items: center; gap: 8px; font-size: 17px; margin: 0 0 6px; color: var(--text); }
.pk-commit-title svg { color: var(--purple); flex-shrink: 0; }
.pk-commit-org { font-size: 14px; color: var(--muted); margin: 0 0 6px; }
.pk-commit-score { font-size: 13px; color: var(--green); margin: 0; }

/* contact */
.pk-terminal { background: var(--panel); border: 1px solid var(--border); border-radius: 14px; overflow: hidden; }
.pk-terminal-body { padding: 20px; font-size: 13px; line-height: 2; }
.pk-terminal-body p { margin: 0; }
.pk-prompt { color: var(--green); margin-right: 6px; }
.pk-out { color: var(--text); margin-bottom: 8px !important; word-break: break-word; }
.pk-contact-actions { display: flex; flex-wrap: wrap; gap: 14px; margin-top: 26px; }

/* footer */
.pk-footer { border-top: 1px solid var(--border); padding: 28px 24px 40px; text-align: center; }
.pk-footer p { margin: 0 0 8px; font-size: 12.5px; color: var(--muted); display: flex; align-items: center; justify-content: center; gap: 6px; }
.pk-footer-muted { opacity: 0.7; }
`;
 